// the spread is a per-viewer convenience: remembered in this browser, 1× when storage is unavailable
const SPREAD_KEY = "scan.spread";
function storedSpread() {
  try { const v = Number(localStorage.getItem(SPREAD_KEY)); return v >= SPREAD_MIN && v <= SPREAD_MAX ? v : 1; } catch { return 1; }
}

const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));


export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" | "definition" }) {
  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
                               staleTime: 30_000, placeholderData: (prev) => prev });
  const [hoverKey, setHoverKey] = useState<string | null>(null);
  const activity = useActivity();
  // when a stage finishes, show its output without a reload
  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
    const vals = new Set(f[d]);
    if (vals.has(v)) vals.delete(v); else vals.add(v);
    const next = { ...f, [d]: vals };
    if (!vals.size) delete next[d];
    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
  });
  const clear = (d?: Dim) => setChosen(({ f, order }) => {
    if (!d) return { f: {}, order: [] };
    const next = { ...f }; delete next[d];
    return { f: next, order: order.filter((x) => x !== d) };
  });
  const [hover, setHover] = useState<Hover | null>(null);
  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
  const [spread, setSpread] = useState(storedSpread);
  useEffect(() => { try { localStorage.setItem(SPREAD_KEY, String(spread)); } catch { /* private mode */ } }, [spread]);
  const nav = useRef(newNav());
  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;

  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);

  // page 2 steps through the pipeline: the stage in view (default: the last one done at this checkpoint)
  const [stageView, setStageView] = useState<Stage | null>(null);
  const done = useMemo(() => stagesDone(structure.data), [structure.data]);
  const stage: Stage = stageView && done.includes(stageView) ? stageView : done[done.length - 1] ?? "areas";
  const step = (d: -1 | 1) => { const i = done.indexOf(stage) + d; if (i >= 0 && i < done.length) setStageView(done[i]); };
  const sceneMask = useMemo(() => (mode === "structure" && stage === "classify" && points.data && structure.data?.ready
    ? classifiedMask(points.data.cols.id, structure.data) : mask), [mode, stage, points.data, structure.data, mask]);
  // an item the stage in view doesn't have yet can't stay selected
  useEffect(() => {
    const k = selected?.sel.kind;
    const need: Stage | null = k === "area" ? "areas" : k === "theme" ? "contextualize" : k === "cluster" ? "cluster" : null;
    if (need && !atLeast(stage, need)) setSelected(null);
  }, [stage]); // eslint-disable-line react-hooks/exhaustive-deps
  // [ and ] step back and forward on page 2 (the arrow keys belong to the checkpoints)
  useEffect(() => {
    if (mode !== "structure") return;
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey || (e.target instanceof HTMLElement && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) && (e.target as HTMLInputElement).type !== "range")) return;
      if (e.key === "[") step(-1);
      if (e.key === "]") step(1);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (selected) setSelected(null); else clear();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selected]);
  // switching pages drops the selection, unless the switch came from the inspector's "view in Structure" link
  const carry = useRef<{ sel: Selection; at: [number, number, number] } | null>(null);
  useEffect(() => { setSelected(carry.current); carry.current = null; setHover(null); }, [mode]);
  // page 3 (Definition): its layer mounts on the first visit and then stays, so leaving can run the car back down;
  // leaving glides the camera home to the volume as it rises again
  const [defSeen, setDefSeen] = useState(mode === "definition");
  const prevMode = useRef(mode);
  useEffect(() => {
    if (mode === "definition") setDefSeen(true);
    else if (prevMode.current === "definition") nav.current.reset++;
    prevMode.current = mode;
  }, [mode]);
  const navigate = useNavigate();
  const { search } = useLocation();
  const openInStructure = (sel: Selection, at: [number, number, number]) => { carry.current = { sel, at }; navigate(`/structure${search}`); };

  return (
    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : mode === "definition" ? "Requirement definitions on today's car at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
      <div className="scan-canvas">
        {points.data && (
          <Canvas dpr={[1, 2]} camera={{ position: HOME, fov: 40, near: 0.05, far: 60 }}
                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
                  onPointerMissed={() => { setSelected(null); if (mode === "definition") selectRequirement(null); }}>
            <Suspense fallback={null}>
              <Scene points={points.data} sources={sources.data} mask={sceneMask} position={position} fromPosition={fromPosition}
                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter}
                     spread={spread} nav={nav} stage={stage}
                     extra={defSeen ? <DefinitionLayer active={mode === "definition"} sweepId={sweepId} /> : null} />
            </Suspense>
          </Canvas>
        )}
        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
      </div>

      {mode === "scan" ? (
        <div className="hud-tl">
          <Readout points={points.data} mask={mask} filter={filter} />
          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
                                     onToggle={toggle} onClear={clear} />}
        </div>
      ) : mode === "structure" ? <Funnel data={structure.data} stage={stage} done={done} onStage={setStageView} onStep={step} /> : <DefinitionHud />}
      {mode !== "definition" && <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />}
      <PageSwitch />
      {points.data && mode !== "definition" && <NavPad spread={spread} onSpread={setSpread} nav={nav} />}

      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
      {selected && mode !== "definition" && <Inspector sel={selected.sel} at={selected.at} mode={mode} onOpenStructure={openInStructure}
                              sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
    </main>
  );
}

/* ------------------------------------------------------------------------------------------- glyphs */
type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
const GLYPH_COLOR: Record<GlyphKind, string> = {
  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
};
function Glyph({ kind }: { kind: GlyphKind }) {
  const c = "currentColor";
  return (
    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
    </svg>
  );
}

/* ------------------------------------------------------------------------------------------- readout */
// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
// While filters are set, every count is what they leave visible.
function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
  const { current, position } = useCheckpoint();
  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
  const s = current?.sources;
  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
  const comments = useMemo(() => {
    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
    let n = 0, nu = 0;
    for (let i = 0; i < points.n; i++) if (mask[i] && points.cols.cp[i] <= position) { n++; if (points.cols.cp[i] === position && position > 1) nu++; }
    return { n, nu };
  }, [filter, points, mask, position, s]);
  const research = (ring: ResearchItem["ring"]) => {
    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new) && passResearch(filter, r));
    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
  };
  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
    { k: "comment", label: "Customer comments", n: comments.n, nu: comments.nu },
    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
    { k: "study", label: "Customer study", n: src?.study.filter((x) => passStudy(filter, x)).length, pub: { label: "public ratings", c: rating } },
    { k: "option", label: "Equipment options", n: src?.options.filter((x) => passOption(filter, x)).length, pub: { label: "product news", c: news } },
    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0 && passSales(filter, r)).length, pub: { label: "public sales", c: pub } },
  ];
  return (
    <dl className="readout" aria-label="Evidence at this checkpoint">
      {cells.map((c) => (
        <div key={c.label}>
          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
          {c.pub && (
            <dd className="readout-pub">
              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
            </dd>
          )}
        </div>
      ))}
    </dl>
  );
}

/* ------------------------------------------------------------------------------------------- filters */
// One chip per dimension, under the readout, always shown. Dimensions in use come first, in the order they were set,
// so choosing a value never moves a chip that is already set. A toggle at the head of the row folds the unused chips
// away (the ones in use stay, so nothing is filtered unseen) and unfolds them to the right again; the choice is kept
// per browser. Hovering a chip opens its values; choosing one closes the list again, so only the choice stays. Car and
// market filter every data type; the other chips belong to one type and carry its glyph (comments: channel, label,
// engine, length; research: trust, topic, fact type; study: result; options: category, availability; sales: year).
const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";

interface FilterProps {
  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
}

const FOLD_KEY = "scan.filters.folded";
const readFolded = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };

function FilterBar(p: FilterProps) {
  const [folded, setFolded] = useState(readFolded);
  const [open, setOpen] = useState<Dim | null>(null);
  const fold = (f: boolean) => {
    setFolded(f); setOpen(null);
    try { localStorage.setItem(FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
  };
  const active = p.order.filter((d) => p.filter[d]?.size);
  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
  return (
    <div className="filters" role="toolbar" aria-label="Filter the scan" data-folded={folded ? "" : undefined}>
      <button className="filters-fold" aria-expanded={!folded} aria-controls="scan-filter-chips"
              aria-label={folded ? "Show all filters" : "Hide unused filters"} title={folded ? "Show all filters" : "Hide unused filters"}
              onClick={() => fold(!folded)}>
        <SlidersHorizontal size={12} aria-hidden />
        {folded && <span>Filter{idle.length ? ` · ${idle.length}` : ""}</span>}
        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
      </button>
      <div className="filters-chips" id="scan-filter-chips">
        {[...active, ...(folded ? [] : idle)].map((d) => (
          <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
        ))}
        {active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
      </div>
    </div>
  );
}

function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
  const meta = DIMS.find((d) => d.id === dim)!;
  const chosen = p.filter[dim];
  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
    [open, dim, p.points, p.sources, p.position, p.filter]);
  const max = Math.max(1, ...values.map((v) => v.n));
  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
  return (
    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
        <span className="fchip-dim">{meta.name}</span>
        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
      </button>
      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
      {open && (
        <div className="fpop">
          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
            {values.map(({ v, name, n }) => (
              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
                <span className="fpop-name">{name}</span>
                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
                <span className="fpop-n">{fmt(n)}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- hover */
const useComment = (id: number | null) =>
  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });

function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
  const q = useComment(id);
  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
  return (
    <div className="hovercard" style={{ left, top }} role="tooltip">
      {id != null ? (
        <>
          <p>{q.data?.text ?? " "}</p>
          {q.data && (
            <div className="hovercard-meta">
              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
            </div>
          )}
        </>
      ) : (
        <>
          <p>{hover.title}</p>
          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- inspector */
const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together.", glyph: "comment" },
  cluster: { name: "Cluster", what: "Signals from many comments that express the same need. Blue = improve, white = keep.", glyph: "comment" },
  theme: { name: "Theme", what: "Related findings grouped by the AI, connected to research, study and options that confirm or contradict them.", glyph: "research" },
  area: { name: "Potential requirement area", what: "Themes the AI grouped into an area a requirement could address. Requirements are drafted in the next step.", glyph: "sales" },
  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
};

const PUBLIC_LAYER: Record<"sales" | "study" | "options", { name: string; what: string; glyph: GlyphKind }> = {
  sales: { name: "Public sales figure", what: "Cited, published figure for this car. Dots and rings sit beside BMW's own bars, never mixed with them.", glyph: "sales" },
  study: { name: "Public rating", what: "Published review, award or study result about this car.", glyph: "study" },
  options: { name: "Product news", what: "Published news about this car's equipment, prices or availability.", glyph: "option" },
};

// Evidence shows the source only; what the AI made of it (signals, theme links) is shown on Structure, with a link across.
function Inspector({ sel, at, mode, onOpenStructure, sales, onClose, cpLabel, structure }: {
  sel: Selection; at: [number, number, number]; mode: "scan" | "structure"; onOpenStructure: (sel: Selection, at: [number, number, number]) => void;
  sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string; structure?: StructurePayload;
}) {
  const L = sel.kind === "research" && sel.item.ring ? PUBLIC_LAYER[sel.item.ring] : LAYER[sel.kind];
  const ai = mode === "structure";
  const bridge = !ai && <StructureLink sel={sel} at={at} structure={structure} cpLabel={cpLabel} onOpen={onOpenStructure} />;
  return (
    <aside className="sheet" aria-label={L.name}>
      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
      <header className="sheet-head">
        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
        <p className="sheet-what">{L.what}</p>
      </header>
      {sel.kind === "comment" && <><CommentBody id={sel.id} cpLabel={cpLabel} />{ai ? <SignalList sourceId={sel.id} /> : bridge}</>}
      {sel.kind === "cluster" && <ClusterBody k={sel.key} data={structure} />}
      {sel.kind === "theme" && <ThemeBody k={sel.key} />}
      {sel.kind === "area" && <AreaBody k={sel.key} data={structure} />}
      {sel.kind === "study" && <><StudyBody s={sel.item} />{ai ? <EvidenceUse type="study" id={sel.item.id} structure={structure} /> : bridge}</>}
      {sel.kind === "option" && (
        <>
          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
          {ai ? <EvidenceUse type="option" id={sel.item.id} structure={structure} /> : bridge}
        </>
      )}
      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
      {sel.kind === "research" && (
        <>
          <h2 className="sheet-title">{sel.item.headline}</h2>
          {(sel.item.value != null || sel.item.yoy != null) && (
            <div className="sheet-figure">
              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
            </div>
          )}
          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
          {ai ? <><EvidenceUse type="research" id={sel.item.id} structure={structure} /><SignalList sourceId={sel.item.id} /></> : bridge}
        </>
      )}
    </aside>
  );
}

// One quiet line on Evidence: whether the AI used this item at this checkpoint, and a jump to Structure with it selected.
// Comments are not selectable on Structure (they fly into their clusters), so a comment opens its cluster instead.
function StructureLink({ sel, at, structure, cpLabel, onOpen }: {
  sel: Selection; at: [number, number, number]; structure?: StructurePayload; cpLabel: (id: string) => string;
  onOpen: (sel: Selection, at: [number, number, number]) => void;
}) {
  if (!structure || (sel.kind !== "comment" && sel.kind !== "research" && sel.kind !== "study" && sel.kind !== "option")) return null;
  const cp = cpLabel(structure.checkpoint);
  let text: string, target: [Selection, [number, number, number]] | null = null;
  if (!structure.ready) text = `Not structured by the AI yet at ${cp}`;
  else if (sel.kind === "comment") {
    const i = structure.member.ids.indexOf(sel.id);
    const c = i >= 0 ? structure.clusters[structure.member.cluster[i]] : undefined;
    text = c ? `Grouped into a cluster at ${cp}` : `Not in a cluster at ${cp}`;
    if (c) target = [{ kind: "cluster", key: c.key }, [c.x, c.y, c.z]];
  } else {
    const type = sel.kind, id = String(sel.item.id);
    const themes = new Set(structure.edges.filter((e) => e.src_type === type && e.src_id === id && e.dst_type === "theme").map((e) => e.dst_id)).size;
    text = themes ? `Used in ${themes} theme${themes > 1 ? "s" : ""} at ${cp}` : `Not used as evidence at ${cp}`;
    if (themes) target = [sel, at];
  }
  return (
    <div className="bridge">
      <span>{text}</span>
      {target && <button className="bridge-go" onClick={() => onOpen(...target)}>View in Structure <ArrowRight size={13} /></button>}
    </div>
  );
}

// Which themes the AI linked this research / study / option item to at this checkpoint, and why. Research, study and
// options are not split into signals like comments: they enter the analysis as evidence for themes.
const RELATION: Record<string, string> = {
  supports: "Supports", contradicts: "Contradicts", competes_with: "Competitor", trend_for: "Trend",
  available_as_option: "Already offered", context: "Context",
};
function EvidenceUse({ type, id, structure }: { type: "research" | "study" | "option"; id: number; structure?: StructurePayload }) {
  if (!structure) return null;
  const edges = structure.ready ? structure.edges.filter((e) => e.src_type === type && e.src_id === String(id) && e.dst_type === "theme") : [];
  const theme = Object.fromEntries((structure.themes ?? []).map((t) => [t.key, t]));
  return (
    <div className="use">
      <div className="label">Used as evidence</div>
      {!structure.ready ? <p className="use-none">The AI has not structured this checkpoint yet.</p>
        : !edges.length ? <p className="use-none">Not linked to any theme at this checkpoint.</p>
        : edges.map((e) => (
          <div key={`${e.relation}>${e.dst_id}`} className="use-row" data-rel={e.relation}>
            <div className="use-head"><span className="use-theme">{theme[e.dst_id]?.title ?? e.dst_id}</span><span className="use-rel">{RELATION[e.relation] ?? e.relation}</span></div>
            {e.why && <p className="use-why">{e.why}</p>}
          </div>
        ))}
    </div>
  );
}

function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
  return (
    <dl className="sheet-facts">
      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
    </dl>
  );
}

function CommentBo

content.content:
1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
2	import { Suspense, useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
3	import { Canvas } from "@react-three/fiber";
4	import { useQuery } from "@tanstack/react-query";
5	import { useLocation, useNavigate } from "react-router-dom";
6	import { ArrowRight, ChevronsLeft, ChevronsRight, ExternalLink, SlidersHorizontal, X } from "lucide-react";
7	import { api } from "@/lib/api";
8	import type { Comment, PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
9	import { AreaBody, ClusterBody, Funnel, SignalList, ThemeBody } from "../structure/panels";
10	import { AgentPanel, useActivity } from "../structure/AgentPanel";
11	import { atLeast, classifiedMask, doneStages as stagesDone, type Stage } from "../structure/stages";
12	import { PageSwitch } from "@/components/PageSwitch";
13	import { Dock } from "@/components/Guide";
14	import { useCheckpoint } from "@/state/checkpoint";
15	import { Scene, TYPE_COLOR, layerOf, studyValue, type Hover } from "./Scene";
16	import { CAR_NAME, MARKET_NAME } from "./layout";
17	import { HOME, NavPad, SPREAD_MAX, SPREAD_MIN, newNav } from "./navigate";
18	import { DIMS, SCOPE_NOTE, commentMask, isActive, keyValues, passOption, passResearch, passSales, passStudy, valueName, type Dim, type Filter, type Scope } from "./filter";
19	import { DefinitionLayer } from "../definition/DefinitionLayer";
20	import { DefinitionHud } from "../definition/DefinitionHud";
21	import { select as selectRequirement } from "../definition/store";
22	import "./scan.css";
23	
24	// the spread is a per-viewer convenience: remembered in this browser, 1× when storage is unavailable
25	const SPREAD_KEY = "scan.spread";
26	function storedSpread() {
27	  try { const v = Number(localStorage.getItem(SPREAD_KEY)); return v >= SPREAD_MIN && v <= SPREAD_MAX ? v : 1; } catch { return 1; }
28	}
29	
30	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
31	
32	
33	export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" | "definition" }) {
34	  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
35	  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
36	                               staleTime: 30_000, placeholderData: (prev) => prev });
37	  const [hoverKey, setHoverKey] = useState<string | null>(null);
38	  const activity = useActivity();
39	  // when a stage finishes, show its output without a reload
40	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
41	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
42	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
43	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
44	  // chosen filter values per dimension, and the order the dimensions were first set in (the chip row keeps it)
45	  const [chosen, setChosen] = useState<{ f: Filter; order: Dim[] }>({ f: {}, order: [] });
46	  const toggle = (d: Dim, v: string) => setChosen(({ f, order }) => {
47	    const vals = new Set(f[d]);
48	    if (vals.has(v)) vals.delete(v); else vals.add(v);
49	    const next = { ...f, [d]: vals };
50	    if (!vals.size) delete next[d];
51	    return { f: next, order: vals.size ? (order.includes(d) ? order : [...order, d]) : order.filter((x) => x !== d) };
52	  });
53	  const clear = (d?: Dim) => setChosen(({ f, order }) => {
54	    if (!d) return { f: {}, order: [] };
55	    const next = { ...f }; delete next[d];
56	    return { f: next, order: order.filter((x) => x !== d) };
57	  });
58	  const [hover, setHover] = useState<Hover | null>(null);
59	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
60	  const [spread, setSpread] = useState(storedSpread);
61	  useEffect(() => { try { localStorage.setItem(SPREAD_KEY, String(spread)); } catch { /* private mode */ } }, [spread]);
62	  const nav = useRef(newNav());
63	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
64	
65	  // the filters work on page 1 only; page 2 hides them, so nothing stays filtered there unseen
66	  const filter = useMemo<Filter | null>(() => (mode === "scan" && isActive(chosen.f) ? chosen.f : null), [mode, chosen]);
67	  const mask = useMemo(() => (points.data ? commentMask(points.data, filter) : new Uint8Array(0)), [points.data, filter]);
68	
69	  // page 2 steps through the pipeline: the stage in view (default: the last one done at this checkpoint)
70	  const [stageView, setStageView] = useState<Stage | null>(null);
71	  const done = useMemo(() => stagesDone(structure.data), [structure.data]);
72	  const stage: Stage = stageView && done.includes(stageView) ? stageView : done[done.length - 1] ?? "areas";
73	  const step = (d: -1 | 1) => { const i = done.indexOf(stage) + d; if (i >= 0 && i < done.length) setStageView(done[i]); };
74	  const sceneMask = useMemo(() => (mode === "structure" && stage === "classify" && points.data && structure.data?.ready
75	    ? classifiedMask(points.data.cols.id, structure.data) : mask), [mode, stage, points.data, structure.data, mask]);
76	  // an item the stage in view doesn't have yet can't stay selected
77	  useEffect(() => {
78	    const k = selected?.sel.kind;
79	    const need: Stage | null = k === "area" ? "areas" : k === "theme" ? "contextualize" : k === "cluster" ? "cluster" : null;
80	    if (need && !atLeast(stage, need)) setSelected(null);
81	  }, [stage]); // eslint-disable-line react-hooks/exhaustive-deps
82	  // [ and ] step back and forward on page 2 (the arrow keys belong to the checkpoints)
83	  useEffect(() => {
84	    if (mode !== "structure") return;
85	    const onKey = (e: KeyboardEvent) => {
86	      if (e.metaKey || e.ctrlKey || e.altKey || (e.target instanceof HTMLElement && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) && (e.target as HTMLInputElement).type !== "range")) return;
87	      if (e.key === "[") step(-1);
88	      if (e.key === "]") step(1);
89	    };
90	    window.addEventListener("keydown", onKey);
91	    return () => window.removeEventListener("keydown", onKey);
92	  });
93	
94	  useEffect(() => {
95	    const onKey = (e: KeyboardEvent) => {
96	      if (e.key !== "Escape") return;
97	      if (selected) setSelected(null); else clear();
98	    };
99	    window.addEventListener("keydown", onKey);
100	    return () => window.removeEventListener("keydown", onKey);
101	  }, [selected]);
102	  // switching pages drops the selection, unless the switch came from the inspector's "view in Structure" link
103	  const carry = useRef<{ sel: Selection; at: [number, number, number] } | null>(null);
104	  useEffect(() => { setSelected(carry.current); carry.current = null; setHover(null); }, [mode]);
105	  // page 3 (Definition): its layer mounts on the first visit and then stays, so leaving can run the car back down;
106	  // leaving glides the camera home to the volume as it rises again
107	  const [defSeen, setDefSeen] = useState(mode === "definition");
108	  const prevMode = useRef(mode);
109	  useEffect(() => {
110	    if (mode === "definition") setDefSeen(true);
111	    else if (prevMode.current === "definition") nav.current.reset++;
112	    prevMode.current = mode;
113	  }, [mode]);
114	  const navigate = useNavigate();
115	  const { search } = useLocation();
116	  const openInStructure = (sel: Selection, at: [number, number, number]) => { carry.current = { sel, at }; navigate(`/structure${search}`); };
117	
118	  return (
119	    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : mode === "definition" ? "Requirement definitions on today's car at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
120	      <div className="scan-canvas">
121	        {points.data && (
122	          <Canvas dpr={[1, 2]} camera={{ position: HOME, fov: 40, near: 0.05, far: 60 }}
123	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
124	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
125	                  onPointerMissed={() => { setSelected(null); if (mode === "definition") selectRequirement(null); }}>
126	            <Suspense fallback={null}>
127	              <Scene points={points.data} sources={sources.data} mask={sceneMask} position={position} fromPosition={fromPosition}
128	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
129	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
130	                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
131	                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} filter={filter}
132	                     spread={spread} nav={nav} stage={stage}
133	                     extra={defSeen ? <DefinitionLayer active={mode === "definition"} sweepId={sweepId} /> : null} />
134	            </Suspense>
135	          </Canvas>
136	        )}
137	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
138	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
139	      </div>
140	
141	      {mode === "scan" ? (
142	        <div className="hud-tl">
143	          <Readout points={points.data} mask={mask} filter={filter} />
144	          {points.data && <FilterBar points={points.data} sources={sources.data} position={position} filter={chosen.f} order={chosen.order}
145	                                     onToggle={toggle} onClear={clear} />}
146	        </div>
147	      ) : mode === "structure" ? <Funnel data={structure.data} stage={stage} done={done} onStage={setStageView} onStep={step} /> : <DefinitionHud />}
148	      {mode !== "definition" && <Dock mode={mode} sel={selected?.sel ?? null} agent={mode === "structure" ? <AgentPanel /> : undefined} running={!!activity.data?.running} />}
149	      <PageSwitch />
150	      {points.data && mode !== "definition" && <NavPad spread={spread} onSpread={setSpread} nav={nav} />}
151	
152	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
153	      {selected && mode !== "definition" && <Inspector sel={selected.sel} at={selected.at} mode={mode} onOpenStructure={openInStructure}
154	                              sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
155	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
156	    </main>
157	  );
158	}
159	
160	/* ------------------------------------------------------------------------------------------- glyphs */
161	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
162	const GLYPH_COLOR: Record<GlyphKind, string> = {
163	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
164	};
165	function Glyph({ kind }: { kind: GlyphKind }) {
166	  const c = "currentColor";
167	  return (
168	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
169	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
170	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
171	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
172	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
173	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
174	    </svg>
175	  );
176	}
177	
178	/* ------------------------------------------------------------------------------------------- readout */
179	// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
180	// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
181	// While filters are set, every count is what they leave visible.
182	function Readout({ points, mask, filter }: { points: PointsPayload | undefined; mask: Uint8Array; filter: Filter | null }) {
183	  const { current, position } = useCheckpoint();
184	  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
185	  const s = current?.sources;
186	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
187	  const comments = useMemo(() => {
188	    if (!filter || !points) return { n: s?.feedback.visible, nu: s?.feedback.new };
189	    let n = 0, nu = 0;
190	    for (let i = 0; i < points.n; i++) if (mask[i] && points.cols.cp[i] <= position) { n++; if (points.cols.cp[i] === position && position > 1) nu++; }
191	    return { n, nu };
192	  }, [filter, points, mask, position, s]);
193	  const research = (ring: ResearchItem["ring"]) => {
194	    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new) && passResearch(filter, r));
195	    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
196	  };
197	  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
198	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
199	    { k: "comment", label: "Customer comments", n: comments.n, nu: comments.nu },
200	    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
201	    { k: "study", label: "Customer study", n: src?.study.filter((x) => passStudy(filter, x)).length, pub: { label: "public ratings", c: rating } },
202	    { k: "option", label: "Equipment options", n: src?.options.filter((x) => passOption(filter, x)).length, pub: { label: "product news", c: news } },
203	    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0 && passSales(filter, r)).length, pub: { label: "public sales", c: pub } },
204	  ];
205	  return (
206	    <dl className="readout" aria-label="Evidence at this checkpoint">
207	      {cells.map((c) => (
208	        <div key={c.label}>
209	          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
210	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
211	          {c.pub && (
212	            <dd className="readout-pub">
213	              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
214	              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
215	            </dd>
216	          )}
217	        </div>
218	      ))}
219	    </dl>
220	  );
221	}
222	
223	/* ------------------------------------------------------------------------------------------- filters */
224	// One chip per dimension, under the readout, always shown. Dimensions in use come first, in the order they were set,
225	// so choosing a value never moves a chip that is already set. A toggle at the head of the row folds the unused chips
226	// away (the ones in use stay, so nothing is filtered unseen) and unfolds them to the right again; the choice is kept
227	// per browser. Hovering a chip opens its values; choosing one closes the list again, so only the choice stays. Car and
228	// market filter every data type; the other chips belong to one type and carry its glyph (comments: channel, label,
229	// engine, length; research: trust, topic, fact type; study: result; options: category, availability; sales: year).
230	const SCOPE_GLYPH: Record<Exclude<Scope, "all">, GlyphKind> = { comment: "comment", research: "research", study: "study", option: "option", sales: "sales" };
231	const isMouse = (e: ReactPointerEvent) => e.pointerType === "mouse";
232	
233	interface FilterProps {
234	  points: PointsPayload; sources: SourcesPayload | undefined; position: number; filter: Filter; order: Dim[];
235	  onToggle: (d: Dim, v: string) => void; onClear: (d?: Dim) => void;
236	}
237	
238	const FOLD_KEY = "scan.filters.folded";
239	const readFolded = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };
240	
241	function FilterBar(p: FilterProps) {
242	  const [folded, setFolded] = useState(readFolded);
243	  const [open, setOpen] = useState<Dim | null>(null);
244	  const fold = (f: boolean) => {
245	    setFolded(f); setOpen(null);
246	    try { localStorage.setItem(FOLD_KEY, f ? "1" : "0"); } catch { /* storage blocked: the choice just isn't kept */ }
247	  };
248	  const active = p.order.filter((d) => p.filter[d]?.size);
249	  const idle = DIMS.map((d) => d.id).filter((d) => !active.includes(d));
250	  return (
251	    <div className="filters" role="toolbar" aria-label="Filter the scan" data-folded={folded ? "" : undefined}>
252	      <button className="filters-fold" aria-expanded={!folded} aria-controls="scan-filter-chips"
253	              aria-label={folded ? "Show all filters" : "Hide unused filters"} title={folded ? "Show all filters" : "Hide unused filters"}
254	              onClick={() => fold(!folded)}>
255	        <SlidersHorizontal size={12} aria-hidden />
256	        {folded && <span>Filter{idle.length ? ` · ${idle.length}` : ""}</span>}
257	        {folded ? <ChevronsRight size={13} aria-hidden /> : <ChevronsLeft size={13} aria-hidden />}
258	      </button>
259	      <div className="filters-chips" id="scan-filter-chips">
260	        {[...active, ...(folded ? [] : idle)].map((d) => (
261	          <Chip key={d} dim={d} {...p} open={open === d} setOpen={(o) => setOpen(o ? d : null)} />
262	        ))}
263	        {active.length > 0 && <button className="filters-clear" onClick={() => p.onClear()}>Clear all <span className="label">Esc</span></button>}
264	      </div>
265	    </div>
266	  );
267	}
268	
269	function Chip({ dim, open, setOpen, ...p }: FilterProps & { dim: Dim; open: boolean; setOpen: (o: boolean) => void }) {
270	  const meta = DIMS.find((d) => d.id === dim)!;
271	  const chosen = p.filter[dim];
272	  const values = useMemo(() => (open ? keyValues(dim, p.points, p.sources, p.position, p.filter) : []),
273	    [open, dim, p.points, p.sources, p.position, p.filter]);
274	  const max = Math.max(1, ...values.map((v) => v.n));
275	  const names = [...(chosen ?? [])].map((v) => valueName(dim, v));
276	  return (
277	    <div className="fchip" data-on={chosen?.size ? "" : undefined} data-open={open ? "" : undefined}
278	         onPointerEnter={(e) => isMouse(e) && setOpen(true)} onPointerLeave={(e) => isMouse(e) && setOpen(false)}>
279	      <button className="fchip-btn" aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen(!open)}>
280	        {meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}
281	        <span className="fchip-dim">{meta.name}</span>
282	        {names.length > 0 && <span className="fchip-val">{names[0]}{names.length > 1 ? ` +${names.length - 1}` : ""}</span>}
283	      </button>
284	      {chosen?.size ? <button className="fchip-x" aria-label={`Clear ${meta.name} filter`} onClick={() => p.onClear(dim)}><X size={12} /></button> : null}
285	      {open && (
286	        <div className="fpop">
287	          <div className="fpop-panel" role="listbox" aria-multiselectable aria-label={meta.name}>
288	            <p className="fpop-scope">{meta.scope !== "all" && <Glyph kind={SCOPE_GLYPH[meta.scope]} />}{SCOPE_NOTE[meta.scope]}</p>
289	            {values.map(({ v, name, n }) => (
290	              <button key={v} role="option" aria-selected={!!chosen?.has(v)} onClick={() => { p.onToggle(dim, v); setOpen(false); }}>
291	                <span className="fpop-name">{name}</span>
292	                <span className="fpop-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
293	                <span className="fpop-n">{fmt(n)}</span>
294	              </button>
295	            ))}
296	          </div>
297	        </div>
298	      )}
299	    </div>
300	  );
301	}
302	
303	/* ------------------------------------------------------------------------------------------- hover */
304	const useComment = (id: number | null) =>
305	  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });
306	
307	function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
308	  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
309	  const q = useComment(id);
310	  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
311	  return (
312	    <div className="hovercard" style={{ left, top }} role="tooltip">
313	      {id != null ? (
314	        <>
315	          <p>{q.data?.text ?? " "}</p>
316	          {q.data && (
317	            <div className="hovercard-meta">
318	              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
319	              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
320	            </div>
321	          )}
322	        </>
323	      ) : (
324	        <>
325	          <p>{hover.title}</p>
326	          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
327	        </>
328	      )}
329	    </div>
330	  );
331	}
332	
333	/* ------------------------------------------------------------------------------------------- inspector */
334	const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
335	  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together.", glyph: "comment" },
336	  cluster: { name: "Cluster", what: "Signals from many comments that express the same need. Blue = improve, white = keep.", glyph: "comment" },
337	  theme: { name: "Theme", what: "Related findings grouped by the AI, connected to research, study and options that confirm or contradict them.", glyph: "research" },
338	  area: { name: "Potential requirement area", what: "Themes the AI grouped into an area a requirement could address. Requirements are drafted in the next step.", glyph: "sales" },
339	  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
340	  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
341	  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
342	  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
343	};
344	
345	const PUBLIC_LAYER: Record<"sales" | "study" | "options", { name: string; what: string; glyph: GlyphKind }> = {
346	  sales: { name: "Public sales figure", what: "Cited, published figure for this car. Dots and rings sit beside BMW's own bars, never mixed with them.", glyph: "sales" },
347	  study: { name: "Public rating", what: "Published review, award or study result about this car.", glyph: "study" },
348	  options: { name: "Product news", what: "Published news about this car's equipment, prices or availability.", glyph: "option" },
349	};
350	
351	// Evidence shows the source only; what the AI made of it (signals, theme links) is shown on Structure, with a link across.
352	function Inspector({ sel, at, mode, onOpenStructure, sales, onClose, cpLabel, structure }: {
353	  sel: Selection; at: [number, number, number]; mode: "scan" | "structure"; onOpenStructure: (sel: Selection, at: [number, number, number]) => void;
354	  sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string; structure?: StructurePayload;
355	}) {
356	  const L = sel.kind === "research" && sel.item.ring ? PUBLIC_LAYER[sel.item.ring] : LAYER[sel.kind];
357	  const ai = mode === "structure";
358	  const bridge = !ai && <StructureLink sel={sel} at={at} structure={structure} cpLabel={cpLabel} onOpen={onOpenStructure} />;
359	  return (
360	    <aside className="sheet" aria-label={L.name}>
361	      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
362	      <header className="sheet-head">
363	        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
364	        <p className="sheet-what">{L.what}</p>
365	      </header>
366	      {sel.kind === "comment" && <><CommentBody id={sel.id} cpLabel={cpLabel} />{ai ? <SignalList sourceId={sel.id} /> : bridge}</>}
367	      {sel.kind === "cluster" && <ClusterBody k={sel.key} data={structure} />}
368	      {sel.kind === "theme" && <ThemeBody k={sel.key} />}
369	      {sel.kind === "area" && <AreaBody k={sel.key} data={structure} />}
370	      {sel.kind === "study" && <><StudyBody s={sel.item} />{ai ? <EvidenceUse type="study" id={sel.item.id} structure={structure} /> : bridge}</>}
371	      {sel.kind === "option" && (
372	        <>
373	          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
374	          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
375	                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
376	          {ai ? <EvidenceUse type="option" id={sel.item.id} structure={structure} /> : bridge}
377	        </>
378	      )}
379	      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
380	      {sel.kind === "research" && (
381	        <>
382	          <h2 className="sheet-title">{sel.item.headline}</h2>
383	          {(sel.item.value != null || sel.item.yoy != null) && (
384	            <div className="sheet-figure">
385	              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
386	              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
387	            </div>
388	          )}
389	          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
390	                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
391	          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
392	          {ai ? <><EvidenceUse type="research" id={sel.item.id} structure={structure} /><SignalList sourceId={sel.item.id} /></> : bridge}
393	        </>
394	      )}
395	    </aside>
396	  );
397	}
398	
399	// One quiet line on Evidence: whether the AI used this item at this checkpoint, and a jump to Structure with it selected.
400	// Comments are not selectable on Structure (they fly into their clusters), so a comment opens its cluster instead.
401	function StructureLink({ sel, at, structure, cpLabel, onOpen }: {
402	  sel: Selection; at: [number, number, number]; structure?: StructurePayload; cpLabel: (id: string) => string;
403	  onOpen: (sel: Selection, at: [number, number, number]) => void;
404	}) {
405	  if (!structure || (sel.kind !== "comment" && sel.kind !== "research" && sel.kind !== "study" && sel.kind !== "option")) return null;
406	  const cp = cpLabel(structure.checkpoint);
407	  let text: string, target: [Selection, [number, number, number]] | null = null;
408	  if (!structure.ready) text = `Not structured by the AI yet at ${cp}`;
409	  else if (sel.kind === "comment") {
410	    const i = structure.member.ids.indexOf(sel.id);
411	    const c = i >= 0 ? structure.clusters[structure.member.cluster[i]] : undefined;
412	    text = c ? `Grouped into a cluster at ${cp}` : `Not in a cluster at ${cp}`;
413	    if (c) target = [{ kind: "cluster", key: c.key }, [c.x, c.y, c.z]];
414	  } else {
415	    const type = sel.kind, id = String(sel.item.id);
416	    const themes = new Set(structure.edges.filter((e) => e.src_type === type && e.src_id === id && e.dst_type === "theme").map((e) => e.dst_id)).size;
417	    text = themes ? `Used in ${themes} theme${themes > 1 ? "s" : ""} at ${cp}` : `Not used as evidence at ${cp}`;
418	    if (themes) target = [sel, at];
419	  }
420	  return (
421	    <div className="bridge">
422	      <span>{text}</span>
423	      {target && <button className="bridge-go" onClick={() => onOpen(...target)}>View in Structure <ArrowRight size={13} /></button>}
424	    </div>
425	  );
426	}
427	
428	// Which themes the AI linked this research / study / option item to at this checkpoint, and why. Research, study and
429	// options are not split into signals like comments: they enter the analysis as evidence for themes.
430	const RELATION: Record<string, string> = {
431	  supports: "Supports", contradicts: "Contradicts", competes_with: "Competitor", trend_for: "Trend",
432	  available_as_option: "Already offered", context: "Context",
433	};
434	function EvidenceUse({ type, id, structure }: { type: "research" | "study" | "option"; id: number; structure?: StructurePayload }) {
435	  if (!structure) return null;
436	  const edges = structure.ready ? structure.edges.filter((e) => e.src_type === type && e.src_id === String(id) && e.dst_type === "theme") : [];
437	  const theme = Object.fromEntries((structure.themes ?? []).map((t) => [t.key, t]));
438	  return (
439	    <div className="use">
440	      <div className="label">Used as evidence</div>
441	      {!structure.ready ? <p className="use-none">The AI has not structured this checkpoint yet.</p>
442	        : !edges.length ? <p className="use-none">Not linked to any theme at this checkpoint.</p>
443	        : edges.map((e) => (
444	          <div key={`${e.relation}>${e.dst_id}`} className="use-row" data-rel={e.relation}>
445	            <div className="use-head"><span className="use-theme">{theme[e.dst_id]?.title ?? e.dst_id}</span><span className="use-rel">{RELATION[e.relation] ?? e.relation}</span></div>
446	            {e.why && <p className="use-why">{e.why}</p>}
447	          </div>
448	        ))}
449	    </div>
450	  );
451	}
452	
453	function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
454	  return (
455	    <dl className="sheet-facts">
456	      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
457	    </dl>
458	  );
459	}
460	
461	function CommentBody({ id, cpLabel }: { id: number; cpLabel: (id: string) => string }) {
462	  const q = useComment(id);
463	  const c = q.data;
464	  if (!c) return <div className="sheet-skel" aria-hidden><span /><span /><span /></div>;
465	  const label = c.bmw_labels?.[0];
466	  return (
467	    <>
468	      <blockquote className="sheet-quote">{c.text}</blockquote>
469	      <Facts rows={[["Car", CAR_NAME[c.car] ?? c.car],
470	                    ["Market", `${MARKET_NAME[c.market] ?? c.market}${c.country && c.country !== c.market ? ` · ${c.country}` : ""}`],
471	                    ["Channel", c.channel], ["Engine", c.engine],
472	                    ["BMW label", `${label?.feedback_type ?? "Unlabelled"}${label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}`],
473	                    ["Acquired", cpLabel(c.checkpoint)], ["ID", c.external_id]]} />
474	    </>
475	  );
476	}
477	
478	function StudyBody({ s }: { s: Extract<Selection, { kind: "study" }>["item"] }) {
479	  const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0));
480	  return (
481	    <>
482	      <h2 className="sheet-title">{s.item}</h2>
483	      <div className="sheet-figure"><span className="num">{studyValue(s)}</span></div>
484	      <div className="zbar" role="img" aria-label={`${z >= 0 ? "Above" : "Below"} this car's average by ${Math.abs(z).toFixed(1)} standard deviations`}>
485	        <span className="zbar-mid" />
486	        <span className="zbar-fill" style={{ left: z >= 0 ? "50%" : `${50 + (z / 2.5) * 50}%`, width: `${(Math.abs(z) / 2.5) * 50}%` }} />
487	        <span className="zbar-l label">below average</span><span className="zbar-r label">above average</span>
488	      </div>
489	      <Facts rows={[["Car", CAR_NAME[s.car] ?? s.car], ["Market", MARKET_NAME[s.market] ?? s.market],
490	                    ["Scale", s.scale === "dist_7" ? "7-point, share of top two answers" : "Mean rating, 0–10"]]} />
491	    </>
492	  );
493	}
494	
495	function SalesBody({ row, all }: { row: Extract<Selection, { kind: "sales" }>["item"]; all: SourcesPayload["sales"] }) {
496	  const series = all.filter((s) => s.car === row.car && s.market === row.market).sort((a, b) => a.year - b.year);
497	  const max = Math.max(1, ...series.map((s) => s.units ?? 0));
498	  return (
499	    <>
500	      <h2 className="sheet-title">{CAR_NAME[row.car] ?? row.car} · {MARKET_NAME[row.market] ?? row.market}</h2>
501	      <div className="minibars" role="img" aria-label="Sales by year">
502	        {series.map((s) => (
503	          <div key={s.year} className="minibar" data-on={s.year === row.year ? "" : undefined} data-forecast={s.is_forecast ? "" : undefined}>
504	            <span className="minibar-n">{fmt(s.units)}</span>
505	            <span className="minibar-col"><span style={{ transform: `scaleY(${(s.units ?? 0) / max})` }} /></span>
506	            <span className="label">{s.year}{s.is_forecast ? " fc" : ""}</span>
507	          </div>
508	        ))}
509	      </div>
510	    </>
511	  );
512	}
