31	  useView((s) => s.pendingLinks);
32	  const { data } = def;
33	
34	  const onLine = useMemo(() => data.requirements.filter((r) => r.lines.includes(line)), [data, line]);
35	  const keys = useMemo(() => new Set(onLine.map((r) => r.key)), [onLine]);
36	  const linksOnLine = data.links.filter((l) => keys.has(l.a) && keys.has(l.b) && linkVerdict(l) !== "removed");
37	  const gaps = onLine.reduce((n, r) => n + r.ladder.filter((x) => x.line === line)
38	    .reduce((m, x) => m + [x.baseline, x.threshold, x.target, x.stretch].filter((l) => l?.basis === "gap").length, 0), 0);
39	  const bundles = data.bundles.filter((b) => b.keys.some((k) => keys.has(k)));
40	  const sel = selected ? data.requirements.find((r) => r.key === selected) ?? null : null;
41	
42	  // the list and inspector sit behind the Requirements pill, top-right next to Audit; one of the two is open at a time.
