44	  const top = useTopPanel();
45	  const showReq = top === "requirements";
46	  useEffect(() => { if (selected && getTopPanel() !== "requirements") setTopPanel("requirements"); }, [selected]);
47	  useEffect(() => { if (top !== "requirements" && getView().selected) select(null); }, [top]);
48	
49	  // a requirement that is not on the chosen line closes; Esc closes the inspector, then clears filters, then the panel
50	  useEffect(() => { if (sel && !sel.lines.includes(line)) select(null); }, [sel, line]);
51	  useEffect(() => {
52	    const onKey = (e: KeyboardEvent) => {
53	      if (e.key !== "Escape") return;
54	      const v = getView();
55	      if (v.selected) select(null);
