166	/* --------------------------------------------------------------------------------------------- hover */
167	function PinHover({ def }: { def: DefData }) {
168	  const hover = useView((s) => s.hover);
169	  const pos = useView((s) => s.hoverPos);
170	  const line = useView((s) => s.line);
