292	function Links({ def, r }: { def: DefData; r: Requirement }) {
293	  const review = useLinkReview(def);
294	  const bundle = useView((s) => s.bundle);
295	  useView((s) => s.pendingLinks);
296	  const [open, setOpen] = useState<{ id: string; verdict: "confirmed" | "removed" } | null>(null);
297	  const [why, setWhy] = useState("");
298	  const mine = def.data.links.filter((l) => l.a === r.key || l.b === r.key).sort((a, b) => b.strength - a.strength);
299	  const byKey = new Map(def.data.requirements.map((x) => [x.key, x]));
300	  const myBundle = def.data.bundles.find((b) => b.keys.includes(r.key));
301	  if (!mine.length) return (
302	    <div className="dblock"><span className="label">Linked requirements</span><p className="use-none">No coupling proposed for this requirement.</p></div>
303	  );
304	  const send = (l: DefLink, verdict: "confirmed" | "removed") => {
305	    if (why.trim().length < 5) return;
306	    review.mutate({ link: l, a: l.a, b: l.b, relation: l.relation, verdict, via: String(l.via), strength: l.strength, rationale: why.trim() });
307	    setOpen(null); setWhy("");
308	  };
309	  return (
310	    <div className="dblock">
311	      <div className="dlinks-head">
312	        <span className="label">Linked requirements</span>
313	        {myBundle && (
314	          <button className="dtext" aria-pressed={bundle === myBundle.id} onClick={() => setView({ bundle: bundle === myBundle.id ? null : myBundle.id })}>
315	            {bundle === myBundle.id ? "Hide bundle" : `Show bundle · ${myBundle.keys.length}`}
316	          </button>
317	        )}
318	      </div>
319	      <ul className="dlinks">
320	        {mine.map((l) => {
321	          const other = byKey.get(l.a === r.key ? l.b : l.a);
322	          const verdict = linkVerdict(l);
323	          const out = l.relation === "enables" ? ((l.a === r.key) === (l.direction !== "b_to_a") ? "enables" : "enabled by") : RELATION_NAME[l.relation].toLowerCase();
324	          const id = String(l.id);
325	          return (
326	            <li key={id} data-removed={verdict === "removed" ? "" : undefined}>
327	              <div className="dlink-top">
328	                <span className="use-rel dlink-rel" data-dashed={isDashed(l.relation) ? "" : undefined}>{out}</span>
329	                <span className="dlink-via">via {l.via}</span>
330	                <span className="dlink-str" aria-label={`strength ${l.strength} of 3`}>{[1, 2, 3].map((i) => <i key={i} data-on={i <= l.strength ? "" : undefined} />)}</span>
331	                {l.state === "new" && <span className="dlink-new label">new</span>}
332	              </div>
333	              {other ? (
334	                <button className="dlink-other" onClick={() => select(other.key)}><PinMark r={other} />{other.title}</button>
335	              ) : <span className="dlink-other">{l.a === r.key ? l.b : l.a}</span>}
336	              <p className="use-why">{l.rationale}</p>
337	              {verdict === "confirmed" || verdict === "removed" ? (
338	                <p className="dlink-review label">{verdict === "confirmed" ? "Confirmed" : "Removed"} by {l.review?.actor ?? "PM"}{l.review?.rationale ? ` · ${l.review.rationale}` : ""}</p>
339	              ) : open?.id === id ? (
340	                <form className="ladder-choose" onSubmit={(e) => { e.preventDefault(); send(l, open.verdict); }}>
341	                  <textarea rows={2} value={why} onChange={(e) => setWhy(e.target.value)} autoFocus
342	                            placeholder={`Why ${open.verdict === "confirmed" ? "confirm" : "remove"} this link? (required)`} aria-label="Rationale" />
343	                  <div className="ladder-actions">
344	                    <button type="submit" className="dbtn primary" disabled={why.trim().length < 5 || review.isPending}>{open.verdict === "confirmed" ? "Confirm link" : "Remove link"}</button>
345	                    <button type="button" className="dbtn" onClick={() => { setOpen(null); setWhy(""); }}>Cancel</button>
346	                  </div>
347	                </form>
348	              ) : (
349	                <div className="dlink-actions">
350	                  <button className="dtext" onClick={() => { setOpen({ id, verdict: "confirmed" }); setWhy(""); }}>Confirm</button>
351	                  <button className="dtext" onClick={() => { setOpen({ id, verdict: "removed" }); setWhy(""); }}>Remove</button>
352	                </div>
353	              )}
354	            </li>
355	          );
356	        })}
357	      </ul>
358	      {review.isError && <p className="derror">Not saved: {(review.error as Error).message}</p>}
359	      {def.sample && <p className="label">Sample data: reviews are kept in this view only.</p>}
360	    </div>
361	  );
362	}
363	// Which top-right panel is open: the audit trail or (on Definition) the requirements. They share the corner, so
364	// opening one closes the other. A tiny external store, read with useSyncExternalStore.
365	import { useSyncExternalStore } from "react";
366	
367	export type TopPanel = "audit" | "requirements" | null;
368	
369	let open: TopPanel = null;
370	const subs = new Set<() => void>();
371	const subscribe = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };
372	
373	export function setTopPanel(next: TopPanel | ((cur: TopPanel) => TopPanel)) {
374	  const v = typeof next === "function" ? next(open) : next;
375	  if (v === open) return;
376	  open = v;
377	  subs.forEach((f) => f());
378	}
379	export const getTopPanel = () => open;
380	export const useTopPanel = () => useSyncExternalStore(subscribe, () => open);
