84:.hovercard {
90:.hovercard p { font-size: 13px; line-height: 1.45; color: var(--ink); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
91:.hovercard-meta { display: flex; align-items: center; gap: 10px; font-size: var(--t-micro); color: var(--ink-3); }
143:.bridge { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding-top: 12px; border-top: 1px solid var(--hair); font-size: var(--t-label); color: var(--ink-3); }
144:.bridge-go { flex: none; display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink-2); transition: color var(--fast); }
145:.bridge-go:hover { color: var(--ink); }
146:.bridge-go svg { transition: transform var(--fast); }
147:.bridge-go:hover svg { transform: translateX(2px); }
/* Page 3, Definition: the car stage's overlays. Same world as the scan: true black, frameless instruments at the
   24px edge, numerals lead, domain hues on the pins only, white = attention, sweep blue only for the PM's choice. */

/* the scan's DOM labels leave with the volume */
.scan[data-mode="definition"] :is(.ring-name, .ring-sub, .time-label, .ring-label, .theme-label, .area-label) { opacity: 0 !important; pointer-events: none; }

/* ------------------------------------------------------------------------------------------- top-left */
.dhud { gap: 14px; width: 340px; }
.dzone-label {
  display: inline-flex; gap: 5px; align-items: baseline; padding: 1px 5px; border-radius: 4px; background: rgba(0, 0, 0, 0.7);
  font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-2); white-space: nowrap; pointer-events: none;
  opacity: 0; transition: opacity var(--fast);
}
.dzone-label b { font-weight: 600; color: var(--ink); }
.dzone:hover .dzone-label, .dzone[data-focus] .dzone-label { opacity: 1; }

/* the shared resource at a link's apex */
.dlink-label {
  padding: 1px 6px; border-radius: 4px; background: rgba(0, 0, 0, 0.72); font-size: var(--t-micro); font-weight: 600; letter-spacing: 0.08em;
  color: var(--ink); white-space: nowrap; pointer-events: none; user-select: none; box-shadow: inset 0 0 0 1px var(--hair-2);
}
.dlink-label[data-dashed] { box-shadow: none; outline: 1px dashed var(--ink-3); outline-offset: -1px; }

/* ------------------------------------------------------------------------------------------- inspector */
.dsheet { gap: 20px; }

